const fs = require('fs');

function run() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    let idx = 0;
    const n = BigInt(input[idx++]);

    if (n <= 2n) {
        console.log("1");
        return;
    }

    let m = 4n;
    let d = 1n;
    while (m + 1n < n) {
        m = 2n * (m + 1n) - d;
        d ^= 1n;
    }

    if (m === n || m + 1n === n) {
        console.log("1");
    } else {
        console.log("0");
    }
}

run();

